package tokenizer

import java.time.{LocalDate, LocalDateTime}
import java.time.format.DateTimeFormatter
import scala.collection.mutable
import scala.util.{Try, Success, Failure}
import io.circe.Json
import io.circe.syntax._

// ============================================================================
// Enums and Constants
// ============================================================================

sealed abstract class TokenType(val value: String)
object TokenType {
  case object STRING extends TokenType("string")
  case object NUMERIC extends TokenType("numeric")
  case object TEMPORAL extends TokenType("temporal")
  case object STRUCTURED extends TokenType("structured")
  case object BINARY extends TokenType("binary")
  case object NULL extends TokenType("null")
}

// ============================================================================
// Protocols / Traits
// ============================================================================

trait Tokenizable {
  def toToken: String
}

trait HasLength {
  def length: Int
}

trait TokenProcessor[-T] {
  def process(item: T): Unit
}

// ============================================================================
// Core Token Classes
// ============================================================================

case class Token(value: String, tokenType: TokenType, metadata: Map[String, Any] = Map.empty) {
  def withMetadata(newMeta: (String, Any)*): Token = {
    copy(metadata = this.metadata ++ newMeta)
  }
}

class MutableTokenBatch(var tokens: mutable.Buffer[Token] = mutable.Buffer.empty, private var _processed: Boolean = false) {
  def add(token: Token): Unit = {
    if (_processed) throw new RuntimeException("Batch already processed")
    tokens += token
  }

  def markProcessed(): Unit = {
    _processed = true
  }
}

// ============================================================================
// Generic Container Classes
// ============================================================================

class TokenContainer[+T](items: Seq[T]) {
  private val _items: Seq[T] = items

  def getAll: Seq[T] = _items

  def size: Int = _items.size

  def mapTokens(func: T => String): Seq[String] = {
    _items.map(func)
  }
}

class TokenSink[-T] {
  private val _received = mutable.Buffer.empty[Any]

  def receive(item: T): Unit = {
    _received += item
  }

  def drain(): Seq[Any] = {
    val result = _received.toSeq
    _received.clear()
    result
  }
}

class BivariantHandler[T](private var _value: T) {
  def get: T = _value

  def set(value: T): Unit = {
    _value = value
  }

  def transform(func: T => T): T = {
    _value = func(_value)
    _value
  }
}

// ============================================================================
// Tokenizer Implementations
// ============================================================================

trait BaseTokenizer[T] {
  def tokenize(value: T): Token

  def tokenizeBatch(values: Iterable[T]): Iterator[Token] = {
    values.iterator.map(tokenize)
  }
}

class StringTokenizer(
    encoding: String = "utf-8",
    normalizer: String => String = identity
) extends BaseTokenizer[Either[String, Array[Byte]]] {

  // Adapting to match Python's StrOrBytes which is Union[str, bytes].
  // In Scala, we can use Either or Any, or overloading. 
  // Given the BaseTokenizer is generic, we try to fit. 
  // But strictly, Python's StringTokenizer handles both.
  // We'll overload or use a type union equivalent (Any/Match).
  // Let's implement specifically for String first as per idiomatic usage,
  // but the class def in Python inherits BaseTokenizer[StrOrBytes].

  def tokenize(value: Either[String, Array[Byte]]): Token = {
    val strValue = value match {
      case Right(bytes) => new String(bytes, encoding)
      case Left(s) => s
    }
    val normalized = normalizer(strValue)
    Token(normalized, TokenType.STRING)
  }

  // Helper for direct usage
  def tokenize(s: String): Token = tokenize(Left(s))
  def tokenize(b: Array[Byte]): Token = tokenize(Right(b))
}

class NumericTokenizer(
    precision: Int = 6,
    formatOptions: Map[String, Any] = Map.empty
) extends BaseTokenizer[Any] { // Using Any to cover Int, Float, BigDecimal

  def tokenize(value: Any): Token = {
    val (strValue, originalType) = value match {
      case d: BigDecimal => (s"%.${precision}f".format(d), "BigDecimal") // simplistic formatting
      case f: Float => (s"%.${precision}f".format(f), "float")
      case d: Double => (s"%.${precision}f".format(d), "float")
      case i: Int => (i.toString, "int")
      case l: Long => (l.toString, "int") // approximate mapping
      case other => (other.toString, other.getClass.getSimpleName)
    }

    Token(strValue, TokenType.NUMERIC, Map("original_type" -> originalType))
  }
}

class TemporalTokenizer(formatStr: Option[String] = None) extends BaseTokenizer[java.time.temporal.TemporalAccessor] {
  private val IsoFormat = DateTimeFormatter.ISO_DATE_TIME
  private val DateFormat = DateTimeFormatter.ISO_DATE

  def tokenize(value: java.time.temporal.TemporalAccessor): Token = {
    val fmt = formatStr.map(DateTimeFormatter.ofPattern).getOrElse {
      value match {
        case _: LocalDateTime => IsoFormat
        case _: LocalDate => DateFormat
        case _ => IsoFormat
      }
    }

    // Formatting can be tricky with TemporalAccessor generic, usually need specific types
    // But basic ISO formatters handle many.
    // For custom patterns, we trust DateTimeFormatter.
    val strValue = try {
        fmt.format(value)
    } catch {
        case _: Exception => value.toString
    }

    Token(strValue, TokenType.TEMPORAL)
  }
}

// ============================================================================
// Advanced: Union Types and Overloads
// ============================================================================

class UniversalTokenizer {
  private val stringTokenizer = new StringTokenizer()
  private val numericTokenizer = new NumericTokenizer()
  private val temporalTokenizer = new TemporalTokenizer()

  def tokenizeNull: Token = Token("NULL", TokenType.NULL)

  def tokenize(value: Any): Token = value match {
    case null => tokenizeNull
    case t: Tokenizable => Token(t.toToken, TokenType.STRUCTURED)
    case s: String => stringTokenizer.tokenize(s)
    case b: Array[Byte] => stringTokenizer.tokenize(b)
    case i: Int => numericTokenizer.tokenize(i)
    case d: Double => numericTokenizer.tokenize(d)
    case f: Float => numericTokenizer.tokenize(f)
