class JsonTokenizer(pretty: Boolean = false) {

  def tokenize(value: Json): Token = {
    val jsonStr = if (pretty) value.spaces2 else value.noSpaces
    Token(jsonStr, TokenType.STRUCTURED, Map("json" -> true))
  }

  def tokenizePath(value: Json, path: String): Option[Token] = {
    val parts = path.split("\\.")

    // Simple path traversal simulation for Circe Json
    // This is a naive implementation matching Python's logic
    var current: io.circe.ACursor = value.hcursor

    for (part <- parts) {
      current = current.downField(part).success.map(_.hcursor)
             .orElse(current.downArray.success.flatMap{c => 
                 // Handle array indexing if part is integer? 
                 // Python: if part.isdigit() -> idx
                 if (part.forall(_.isDigit)) {
                     // In Circe, downArray goes to first. We need Nth. 
                     // Reset to array and move N times? 
                     // Or use downN(n)
                     val idx = part.toInt
                     // We need to go back up? No, current is cursor.
                     // But wait, downField("0") doesn't work for array.
                     // We need to differentiate dict key vs list index.
                     // Circe cursor navigation is typed.
                     // If current focus is Array, we use downN
                     // If Object, downField.
                     // Python logic:
                     // if isinstance(current, dict) and part in current
                     // elif isinstance(current, list) and part.isdigit()

                     // We can try both?
                     None // Complex with ACursor to switch strategy dynamically
                 } else None
             }).getOrElse(current) // Fallback logic is tricky here matching Python exact path

      // Let's implement more directly using generic Json traversal
    }

    // Re-implementing traversal using Json directly for simplicity matching Python logic
    def traverse(j: Json, p: Seq[String]): Option[Json] = {
        if (p.isEmpty) Some(j)
        else {
            val head = p.head
            val tail = p.tail

            // Try Object
            j.asObject.flatMap(_(head)).flatMap(traverse(_, tail))
            .orElse {
                // Try Array
                if (head.forall(_.isDigit)) {
                    val idx = head.toInt
                    j.asArray.flatMap(arr => if (idx >= 0 && idx < arr.length) Some(arr(idx)) else None)
                             .flatMap(traverse(_, tail))
                } else None
            }
        }
    }

    traverse(value, parts.toSeq).map(tokenize)
  }
}

// ============================================================================ 
// Whitespace Tokenizer
// ============================================================================ 

class WhitespaceTokenizer(
    lowercase: Boolean = false,
    minLength: Int = 0,
    maxLength: Option[Int] = None,
    stripPunctuation: Boolean = false
) {
  private val Punctuation = ".,!?;:'\"()[]{}"

  private def processToken(word: String): Option[String] = {
    var w = word
    if (stripPunctuation) {
      w = w.dropWhile(c => Punctuation.contains(c)).reverse.dropWhile(c => Punctuation.contains(c)).reverse
    }

    if (lowercase) {
      w = w.toLowerCase
    }

    if (w.length < minLength) return None

    if (maxLength.isDefined && w.length > maxLength.get) {
      w = w.substring(0, maxLength.get)
    }

    if (w.isEmpty) None else Some(w)
  }

  def tokenize(text: String): Seq[Token] = {
    val words = text.split("\\s+")
    words.zipWithIndex.flatMap { case (word, i) =>
      processToken(word).map {
        processed =>
        Token(processed, TokenType.STRING, Map("position" -> i, "original" -> word))
      }
    }.toSeq
  }

  def tokenizeToStrings(text: String): Seq[String] = {
    tokenize(text).map(_.value)
  }

  def tokenizeWithPositions(text: String): Seq[(String, Int, Int)] = {
    // Re-implement logic to find positions
    // Python implementation tracks current_pos
    val result = mutable.Buffer.empty[(String, Int, Int)]
    var currentPos = 0
    val words = text.split("\\s+") // This split might lose original spacing info which makes finding position harder if multiple spaces

    // Python's split() without args splits by whitespace runs and discards empty strings.
    // To find exact position, we must search in text. 

    for (word <- words) {
        if (word.nonEmpty) {
            val start = text.indexOf(word, currentPos)
            if (start != -1) {
                val end = start + word.length
                processToken(word).foreach {
                    processed =>
                    result += ((processed, start, end))
                }
                currentPos = end
            }
        }
    }
    result.toSeq
  }

  def countTokens(text: String): Int = tokenize(text).length
}

