// Builder Pattern
// ============================================================================ 

object TokenizerBuilder {
    def apply[T](): TokenizerBuilder[T] = new TokenizerBuilder[T]()
}

class TokenizerBuilder[T] {
  private val _normalizers = mutable.Buffer.empty[String => String]
  private val _validators = mutable.Buffer.empty[T => Boolean]
  private var _metadata = Map.empty[String, Any]

  def withNormalizer(normalizer: String => String): this.type = {
    _normalizers += normalizer
    this
  }

  def withValidator(validator: T => Boolean): this.type = {
    _validators += validator
    this
  }

  def withMetadata(kwargs: (String, Any)*): this.type = {
    _metadata ++= kwargs
    this
  }

  def build(): T => Token = {
    val normalizers = _normalizers.toSeq
    val validators = _validators.toSeq
    val metadata = _metadata

    (value: T) => {
      // Validate
      validators.foreach {
        validator =>
        if (!validator(value)) {
           throw new IllegalArgumentException(s"Validation failed for $value")
        }
      }

      var strValue = value.toString

      // Normalize
      normalizers.foreach {
        normalizer =>
        strValue = normalizer(strValue)
      }

      Token(strValue, TokenType.STRING, metadata)
    }
  }
}
